95: function TreeItem({ node, depth = 0 }: { node: TreeNode; depth?: number }) {
96:   const [open, setOpen] = useState(depth < 1);
97:   const isFolder = node.type === 'folder';
98: 
99:   return (
100:     <div>
101:       <button
102:         onClick={() => isFolder && setOpen(!open)}
103:         className="w-full flex items-center gap-2 py-1.5 rounded-lg text-xs hover:bg-white/[0.05] transition-colors"
104:         style={{ paddingLeft: `${depth * 12 + 8}px` }}
105:       >
106:         {isFolder ? (
107:           open
108:             ? <ChevronDown size={11} className="text-slate-500 shrink-0" />
109:             : <ChevronRight size={11} className="text-slate-500 shrink-0" />
110:         ) : (
111:           <File size={11} className="text-slate-500 shrink-0 ml-0.5" />
112:         )}
113:         {isFolder && <FolderOpen size={12} className="text-amber-400/70 shrink-0" />}
114:         <span className={`truncate text-[11px] ${isFolder ? 'text-slate-200 font-medium' : 'text-slate-500'}`}>
115:           {node.name}
116:         </span>
117:       </button>
118:       <AnimatePresence>
119:         {isFolder && open && node.children && (
120:           <motion.div
121:             initial={{ height: 0, opacity: 0 }}
122:             animate={{ height: 'auto', opacity: 1 }}
123:             exit={{ height: 0, opacity: 0 }}
124:             transition={{ duration: 0.18 }}
125:             className="overflow-hidden"
126:           >
127:             {node.children.map(child => (
128:               <TreeItem key={child.name} node={child} depth={depth + 1} />
129:             ))}
130:           </motion.div>
131:         )}
132:       </AnimatePresence>
133:     </div>
134:   );
135: }
